// Industrial PLC Motor Interlock Logic
#include <iostream>

struct SafetySensors {
    bool emergencyStop;
    bool thermalOverload;
    bool pressureOk;
};

bool evaluateMotorRunPermission(SafetySensors s, bool startCmd) {
    bool safetyChain = (!s.emergencyStop) && (!s.thermalOverload) && s.pressureOk;
    static bool motorLatched = false;
    if (!safetyChain) {
        motorLatched = false;
    } else if (startCmd) {
        motorLatched = true;
    }
    return motorLatched;
}
